require_once __DIR__.'/../lib/AppContent.php';
$host=$_SERVER['HTTP_HOST']??'';
if(!in_array($_SERVER['REMOTE_ADDR']??'',['127.0.0.1','::1'],true)||!preg_match('/^(?:127\.0\.0\.1|localhost)(?::\d+)?$/D',$host)){http_response_code(403);echo 'Local access only';return;}
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');
$nonce=base64_encode(random_bytes(18));header("Content-Security-Policy: default-src 'none'; script-src 'nonce-$nonce'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'");
session_name('betleriz_admin');session_set_cookie_params(['httponly'=>true,'samesite'=>'Strict','path'=>'/admin']);session_start();$_SESSION['csrf']??=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='POST'){
 header('Content-Type: application/json; charset=utf-8');
 if(($_SERVER['HTTP_ORIGIN']??'')!=='http://'.$host||!hash_equals($_SESSION['csrf'],(string)($_SERVER['HTTP_X_CSRF_TOKEN']??''))){http_response_code(403);echo '{"success":false,"error":"forbidden"}';return;}
 if((int)($_SERVER['CONTENT_LENGTH']??0)>1000000){http_response_code(413);return;}
 try{$input=json_decode(file_get_contents('php://input'),true,512,JSON_THROW_ON_ERROR);if(!is_array($input))throw new RuntimeException('invalid_content');$saved=(new AppContent())->save($input,(int)($input['revision']??0));echo json_encode(['success'=>true,'data'=>$saved],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP);}
 catch(Throwable $e){$known=['revision_conflict','invalid_content','invalid_store','invalid_store_url','store_url_required','invalid_email','invalid_pages','invalid_page','invalid_translation','published_translation_required','too_many_pages'];$error=in_array($e->getMessage(),$known,true)?$e->getMessage():'save_failed';http_response_code($error==='revision_conflict'?409:400);echo json_encode(['success'=>false,'error'=>$error]);}return;
}
if($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);return;}
