header('Content-Type: text/html; charset=utf-8');
?><!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Betleriz · Yerel içerik yönetimi</title><style>*{box-sizing:border-box}body{margin:0;background:#101018;color:#faf7ff;font:15px system-ui}main{max-width:1000px;margin:auto;padding:30px 24px}h1{color:#ae63ff}h2{font-size:20px}section{padding:24px;border:1px solid #3a2c48;border-radius:20px;background:#1c1726;margin:20px 0}label{display:block;color:#cdbddd;margin:16px 0 6px}input,select,textarea{width:100%;font:inherit;padding:12px;color:white;background:#101018;border:1px solid #665075;border-radius:9px}textarea{min-height:280px;line-height:1.6}button{background:#ae63ff;color:#101018;border:0;border-radius:10px;padding:14px 22px;font-weight:800;cursor:pointer}button:disabled{opacity:.5}a{color:#cf9bff}p{color:#b5abc2;line-height:1.7}.row{display:grid;grid-template-columns:1fr 1fr;gap:20px}#message{color:#ffad62;white-space:pre-wrap}input[type=checkbox]{width:auto}.bar{position:sticky;bottom:0;background:#101018;padding:18px 0;border-top:1px solid #3a2c48}@media(max-width:600px){.row{grid-template-columns:1fr}}</style><main><h1>betleriz<span style="color:#ff7a00">.</span> İçerik yönetimi</h1><p>Bu ekran yalnızca bu Mac'ten erişilebilir. Mağaza adresleri ve bilgi sayfaları buradan kaydedilir; uygulama açıldığında veya bilgiler yenilendiğinde backend'den okunur.</p><section><h2>Tahminler ve krediler</h2><p><a href="/admin/tips">Güncel tahmin yayımla ve kredi ürünlerini görüntüle</a></p></section><section><h2>Mağaza bağlantıları</h2><div class="row"><div><label for="android-status">Android durumu</label><select id="android-status"><option value="soon">Yakında</option><option value="available">Yayında</option></select><label for="android-url">Google Play adresi</label><input type="url" id="android-url" placeholder="https://play.google.com/store/apps/details?id=com.betleriz.app"></div><div><label for="ios-status">iOS durumu</label><select id="ios-status"><option value="soon">Yakında</option><option value="available">Yayında</option></select><label for="ios-url">App Store adresi</label><input type="url" id="ios-url" placeholder="https://apps.apple.com/..."></div></div><label for="email">Destek e-posta adresi</label><input id="email" type="email" placeholder="Gerçek destek adresini girin"></section><section><h2>Bilgilendirme sayfaları</h2><p>Metinler düz yazı olarak kaydedilir. Taslaklar uygulamada ve tarayıcıda taslak uyarısıyla görünür. Yayın öncesinde gerçek işletme, veri işleme ve iletişim bilgilerini tamamlayın.</p><div class="row"><div><label for="page">Sayfa</label><select id="page"></select></div><div><label for="language">İçerik dili</label><select id="language"></select></div></div><label for="status">Yayın durumu</label><select id="status"><option value="draft">Taslak</option><option value="published">Yayında</option></select><label><input type="checkbox" id="active"> Uygulamada ve tarayıcıda göster</label><label for="title">Başlık</label><input id="title"><label for="body">Sayfa içeriği</label><textarea id="body"></textarea><p><a id="preview" target="_blank" rel="noopener">Tarayıcıda aç ↗</a></p></section><div class="bar"><button id="save">Değişiklikleri kaydet</button> <a href="/api/app-config.php?lang=tr" target="_blank" rel="noopener">API yanıtı</a><p id="message" role="status"></p></div></main><script nonce="<?=htmlspecialchars($nonce,ENT_QUOTES)?>">
let config=<?=json_encode($content,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?>;
const csrf=<?=json_encode($_SESSION['csrf'])?>;
const $=id=>document.getElementById(id),names={tr:'Türkçe',en:'English',az:'Azərbaycanca',ur:'اردو',hi:'हिन्दी',th:'ไทย',id:'Bahasa Indonesia',ar:'العربية',ku:'Kurdî (Kurmancî)'};
for(const [code,label] of Object.entries(names))$('language').add(new Option(label,code));
function selected(){return config.pages.find(p=>p.id===$('page').value)}
function load(){const p=selected(),lang=$('language').value,text=p.translations[lang];$('title').value=text.title;$('body').value=text.content;$('body').dir=$('title').dir=['ar','ur'].includes(lang)?'rtl':'ltr';$('active').checked=p.active;$('status').value=p.status;$('preview').href='/pages/'+p.id+'?lang='+lang;}
function init(){for(const platform of ['android','ios']){$(platform+'-status').value=config.stores[platform].status;$(platform+'-url').value=config.stores[platform].url;}$('email').value=config.supportEmail;const id=$('page').value;$('page').replaceChildren();for(const p of config.pages)$('page').add(new Option(p.translations.tr.title,p.id));if(config.pages.some(p=>p.id===id))$('page').value=id;load();}
$('page').onchange=$('language').onchange=load;
$('title').oninput=()=>selected().translations[$('language').value].title=$('title').value;
$('body').oninput=()=>selected().translations[$('language').value].content=$('body').value;
$('active').onchange=()=>selected().active=$('active').checked;
$('status').onchange=()=>selected().status=$('status').value;
$('save').onclick=async()=>{
 for(const platform of ['android','ios'])config.stores[platform]={status:$(platform+'-status').value,url:$(platform+'-url').value.trim()};config.supportEmail=$('email').value.trim();$('save').disabled=true;$('message').textContent='Kaydediliyor…';
 try{const response=await fetch('/admin',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(config)});const result=await response.json();if(!response.ok||!result.success)throw Error(result.error);config=result.data;init();$('message').textContent='Kaydedildi. Uygulamada bilgileri yenile düğmesine basın. Sürüm: '+config.revision;}catch(e){const messages={revision_conflict:'İçerik başka bir pencerede değişti. Sayfayı yenileyin ve tekrar düzenleyin.',invalid_store_url:'Mağaza adresi https://play.google.com veya https://apps.apple.com üzerinde olmalı.',store_url_required:'Yayında seçilen mağaza için adres girin.',invalid_email:'Geçerli bir destek e-posta adresi girin.',published_translation_required:'Yayına almak için dokuz dilin başlık ve içeriklerini tamamlayın.'};$('message').textContent=messages[e.message]||'Kaydedilemedi: '+e.message;}finally{$('save').disabled=false;}
};init();
</script></html>
